SELECT * FROM (SELECT level, CASE WHEN salary >= 132000 THEN 'high' WHEN salary >= 76000 THEN 'mid' ELSE 'low' END AS salary_bucket, MAX(salary) - MIN(salary) AS salary_range, COUNT(CASE WHEN level = 'L2' THEN 1 END) AS l2_count FROM employees GROUP BY level, CASE WHEN salary >= 132000 THEN 'high' WHEN salary >= 76000 THEN 'mid' ELSE 'low' END) AS t WHERE salary_range > 77 ORDER BY salary_range DESC;
